import {analyze} from './detector.mjs';
const $=s=>document.querySelector(s);
const node=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
const evidence=(id,title,quote,why)=>({id,title,quotes:[quote],why});
const cases=[
 {title:'The helpful stranger.',subtitle:'Support has entered the chat.',category:'IMPERSONATION / SMS',sender:'Support team',detail:'Unknown number · Today, 10:42',avatar:'?',channel:'TEXT MESSAGE',suspicious:true,parts:["Hi, this is support. We noticed unusual activity on your account. ",{text:'Send us the six-digit code',clue:evidence('secrets','Your code is the key.','six-digit code','A login code can unlock your account. Never send it to someone in a message, even if they claim to be support.')}," you just received so we can secure it. Please respond ",{text:'within 10 minutes',clue:evidence('pressure','A deadline designed to rush you.','within 10 minutes','Time pressure discourages you from checking. Real or fake, the request can be verified independently.')}," or your account will be suspended."],explanation:'The request for a login code is the giveaway. Urgency adds pressure. Open the company’s known app yourself and ask support there.'},
 {title:'The parcel plot twist.',subtitle:'One tiny fee. One big question.',category:'DELIVERY / SMS',sender:'Parcel updates',detail:'Unknown number · Today, 11:08',avatar:'↗',channel:'TEXT MESSAGE',suspicious:true,parts:["Your parcel could not be delivered. Please pay a ",{text:'RM2.50 redelivery fee',clue:evidence('payment','A small fee can be the bait.','RM2.50 redelivery fee','A tiny amount can make a request feel harmless while a fake payment page collects your card details.')}," at ",{text:'https://parcel-redelivery.example',clue:evidence('link','Where does that link really go?','parcel-redelivery.example','The destination is unverified. Check delivery status through the courier’s known app or website, rather than the message link.')},". Your parcel will be returned if payment is not made ",{text:'today',clue:evidence('pressure','The pressure is part of the pitch.','today','A threatened return adds urgency. Check using your existing order or tracking information before paying.')},"."],explanation:'A payment request, an unverified link, and a deadline deserve a pause. Use your order’s tracking information to check directly with the courier.'},
 {title:'Lunch, or a long con?',subtitle:'Not every message is a mystery.',category:'EVERYDAY LIFE / CHAT',sender:'A friend',detail:'Saved contact · Today, 11:26',avatar:'A',channel:'CHAT MESSAGE',suspicious:false,parts:["Hey! Lunch at ",{text:'the same café as last week',clue:evidence('context','A piece of familiar context.','the same café as last week','This sounds like an ordinary plan, without a request for money or secrets. Familiar context alone does not verify the sender, though.')},"? I can make 12:30 tomorrow. No worries if you’re busy — we can do another day."],explanation:'No obvious request for money, secrets, or rushed action appears here. That is not proof of identity. If the contact or plan is unfamiliar, check through a known channel.'},
 {title:'You won! (Did you?)',subtitle:'The prize comes with a catch.',category:'PRIZE BAIT / EMAIL',sender:'Rewards desk',detail:'Unfamiliar sender · Today, 12:03',avatar:'★',channel:'EMAIL EXCERPT',suspicious:true,parts:["Congratulations! You have ",{text:'won RM5,000',clue:evidence('reward','An unexpected windfall.','won RM5,000','A prize you did not expect can be bait, especially if you did not enter a draw.')},". Just send a ",{text:'RM50 processing fee',clue:evidence('payment','Paying to unlock a prize.','RM50 processing fee','An upfront fee to receive a reward is a warning sign. Check the promotion independently before sending money.')}," to receive your reward. ",{text:'Keep this secret',clue:evidence('secrecy','Why the secrecy?','Keep this secret','Secrecy can stop you asking someone who might help you question the offer.')}," until the funds reach your account."],explanation:'The combination matters: an unexpected prize, a fee, and secrecy. Do not pay to unlock it. Verify any claimed promotion through the real company.'},
 {title:'The money machine.',subtitle:'A promise with no downside?',category:'INVESTMENT PITCH / CHAT',sender:'Wealth mentor',detail:'Unsolicited chat · Today, 12:47',avatar:'↑',channel:'CHAT MESSAGE',suspicious:true,parts:["Our exclusive group offers ",{text:'guaranteed RM800 daily profit',clue:evidence('reward','A guarantee worth questioning.','guaranteed RM800 daily profit','Guaranteed profit claims deserve skepticism. A confident claim is not evidence of a genuine investment.')},". ",{text:'Deposit RM100',clue:evidence('payment','The upfront commitment.','Deposit RM100','An unsolicited request for a deposit can be a trap. Research the provider independently before sending any money.')}," to activate your account. ",{text:'Last chance — act now',clue:evidence('pressure','FOMO is doing the selling.','Last chance — act now','Scarcity and urgency can distract you from checking who is making the offer.')},"!"],explanation:'Guaranteed profits, an upfront deposit, and pressure to act form a cluster of warning signs. Stop and independently verify the provider before any payment.'}
];
let current=0, mode='training', pinned=new Map(),answers=new Map(),revealed=false,customText='';
const list=$('#case-list');
function updateList(){list.replaceChildren();cases.forEach((c,i)=>{const b=node('button','','case-row'+(mode==='training'&&i===current?' active':'')+(answers.has(i)?' solved':''));b.setAttribute('aria-label',`Case ${i+1}: ${c.title}${answers.has(i)?', reviewed':''}`);if(mode==='training'&&i===current)b.setAttribute('aria-current','true');const text=node('span');text.append(node('span',c.title,'case-row-title'),node('span',c.subtitle,'case-row-subtitle'),node('span',answers.has(i)?'FILE REVIEWED':'CASE FILE / '+String(i+1).padStart(3,'0'),'case-row-tag'));b.append(node('span',String(i+1).padStart(2,'0'),'case-num'),text,node('span','','row-dot'));b.addEventListener('click',()=>openCase(i));list.append(b);});$('#case-counter').textContent=`${answers.size} / 5 FILED`;const correct=[...answers.values()].filter(Boolean).length;$('#detective-rank').textContent=answers.size===5?(correct===5?'Chief of trust issues':correct>=3?'Sharp-eyed investigator':'Detective in training'):'Unlicensed detective';$('#detective-score').textContent=answers.size?`${correct} correct · ${answers.size} file${answers.size===1?'':'s'} reviewed`:'Everyone starts somewhere.';}
function setPanel(panel){$('.workspace').dataset.mobilePanel=panel;document.querySelectorAll('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===panel);b.setAttribute('aria-pressed',String(b.dataset.panel===panel));});$('#notebook').classList.remove('show-notebook');if(matchMedia('(max-width:650px)').matches)window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
$('#notes-toggle').addEventListener('click',()=>{if(matchMedia('(max-width:650px)').matches)setPanel('notebook');else $('#notebook').classList.toggle('show-notebook');});
$('#notes-close').addEventListener('click',()=>$('#notebook').classList.remove('show-notebook'));
function noteArticle(clue,i){const item=node('article','','clue-note');const heading=node('div','','clue-note-heading');heading.append(node('span',String(i+1).padStart(2,'0')),node('h3',clue.title));item.append(heading,node('q',clue.quotes.join(' · ')),node('p',clue.why));return item;}
function renderNotes(all){const container=$('#notes-body');container.replaceChildren();const clues=all||[...pinned.values()];$('#clue-count').textContent=`${pinned.size} clue${pinned.size===1?'':'s'} pinned`;$('#notes-count').textContent=clues.length;if(!clues.length){if(revealed){container.append(node('p','No obvious warning patterns were found. That does not establish that the message is genuine. Verify the sender and context independently.','notes-intro'));}else{const intro=node('p','','notes-intro');intro.append(node('b','Your gut has entered the chat.'),document.createTextNode(' Tap underlined phrases in the message to pin your evidence here.'));const empty=node('div','','notes-empty');empty.append(node('span','⌕','doodle-search'),node('p','No clues pinned. Yet.\nGood detectives look twice.'));container.append(intro,empty);}}else{container.append(node('p',revealed?'THE EVIDENCE, UNPACKED':`${clues.length} OBSERVATION${clues.length===1?'':'S'} PINNED`,'notes-summary'));clues.forEach((clue,i)=>container.append(noteArticle(clue,i)));}}
function makeEvidence(part,index){const b=node('button',part.text,'evidence-word');b.dataset.clue=String(index);b.setAttribute('aria-pressed',String(pinned.has(index)));b.classList.toggle('selected',pinned.has(index));b.classList.toggle('revealed',revealed);b.setAttribute('aria-label',`Investigate: ${part.text}`);b.addEventListener('click',()=>{if(revealed)return;if(pinned.has(index))pinned.delete(index);else pinned.set(index,part.clue);b.classList.toggle('selected',pinned.has(index));b.setAttribute('aria-pressed',String(pinned.has(index)));renderNotes();});return b;}
function renderMessage(){const container=$('#message-content');container.replaceChildren();container.classList.toggle('own-case-message',mode==='lab');if(mode==='lab'){highlightCustom(customText,analyze(customText).findings);return;}cases[current].parts.forEach((part,i)=>container.append(typeof part==='string'?document.createTextNode(part):makeEvidence(part,i)));}
function resetDesk(){pinned=new Map();revealed=false;$('#case-outcome').hidden=true;$('#case-outcome').replaceChildren();$('#next-case').hidden=true;$('#verdict-buttons').hidden=false;$('#desk').classList.remove('lab-mode');$('#case-status').classList.remove('closed');$('#case-status').replaceChildren(node('i'),document.createTextNode(' OPEN CASE'));$('#document-hint').textContent='↑ Tap anything that makes you suspicious.';}
function openCase(index){current=index;mode='training';resetDesk();const c=cases[index];$('#case-category').textContent=c.category;$('#case-title').textContent=c.title;$('#crumb').textContent='Case files';$('#crumb-id').textContent=String(index+1).padStart(3,'0');$('#channel-label').textContent=c.channel;$('#sender-name').textContent=c.sender;$('#sender-detail').textContent=c.detail;$('#sender-avatar').textContent=c.avatar;renderMessage();renderNotes();updateList();setPanel('desk');if(answers.has(index))showOutcome(answers.get(index),false);}
function caseClues(){return cases[current].parts.filter(p=>typeof p!=='string').map(p=>p.clue);}
function showOutcome(correct,record=true){revealed=true;if(record)answers.set(current,correct);$('#verdict-buttons').hidden=true;$('#case-status').classList.add('closed');$('#case-status').replaceChildren(node('i'),document.createTextNode(' FILE REVIEWED'));$('#document-hint').textContent='Evidence unpacked. Open your case notes for the details.';renderMessage();renderNotes(caseClues());const outcome=$('#case-outcome');outcome.replaceChildren(node('span',correct?'INSTINCTS: SHARP':'LESSON: LEARNED','outcome-stamp'),node('h3',correct?'You’re getting hard to fool.':'One for your detective notebook.'),node('p',cases[current].explanation));outcome.hidden=false;$('#next-case').hidden=false;$('#next-case').replaceChildren(document.createTextNode(answers.size===5?'All files reviewed · Start again':'Open the next case'),node('span',answers.size===5?'↺':'→'));updateList();if(correct&&record)celebrate();}
document.querySelectorAll('[data-verdict]').forEach(b=>b.addEventListener('click',()=>{if(revealed||mode!=='training')return;showOutcome((b.dataset.verdict==='true')===cases[current].suspicious);}));
$('#next-case').addEventListener('click',()=>{if(answers.size===cases.length){answers.clear();openCase(0);}else{let next=cases.findIndex((_,i)=>i>current&&!answers.has(i));if(next<0)next=cases.findIndex((_,i)=>!answers.has(i));openCase(next);}});
$('#reset').addEventListener('click',()=>{answers.clear();openCase(0);});
const dialogs=['compose','guide','help','about'];for(const id of dialogs){const button=$('#'+(id==='compose'?'compose':id+'-open'));button.addEventListener('click',()=>$('#'+id+'-dialog').showModal());}
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#custom-message').addEventListener('input',()=>{$('#char-count').textContent=`${$('#custom-message').value.length} / 6000`;$('#custom-message').setCustomValidity('');});
function highlightCustom(text,findings){const root=$('#message-content');root.replaceChildren();const ranges=[];findings.forEach(f=>f.quotes.forEach(quote=>{let from=0;const lower=text.toLowerCase(),needle=quote.toLowerCase();while(needle&&from<text.length){const start=lower.indexOf(needle,from);if(start<0)break;ranges.push({start,end:start+quote.length,clue:f});from=start+quote.length;}}));ranges.sort((a,b)=>a.start-b.start||b.end-a.end);let at=0;for(const range of ranges){if(range.start<at)continue;root.append(document.createTextNode(text.slice(at,range.start)));const mark=node('mark',text.slice(range.start,range.end),'evidence-word revealed');root.append(mark);at=range.end;}root.append(document.createTextNode(text.slice(at)));}
$('#compose-form').addEventListener('submit',event=>{event.preventDefault();const input=$('#custom-message');if(!input.value.trim()){input.setCustomValidity('Add a message to investigate.');input.reportValidity();return;}customText=input.value;mode='lab';resetDesk();mode='lab';revealed=true;$('#desk').classList.add('lab-mode');$('#compose-dialog').close();$('#case-category').textContent='PRIVATE INVESTIGATION / YOUR MESSAGE';$('#case-title').textContent='Let’s read between the lines.';$('#crumb').textContent='Message lab';$('#crumb-id').textContent='LOCAL';$('#channel-label').textContent='YOUR MESSAGE';$('#sender-name').textContent='Unverified sender';$('#sender-detail').textContent='Pasted by you · Processed on this device';$('#sender-avatar').textContent='⌕';$('#document-hint').textContent='Highlighted phrases matched common warning patterns.';const result=analyze(customText);renderMessage();renderNotes(result.findings);$('#case-status').replaceChildren(node('i'),document.createTextNode(' PATTERN CHECK'));$('#verdict-buttons').hidden=true;const out=$('#case-outcome');out.replaceChildren(node('span',`${result.findings.length} WARNING PATTERN${result.findings.length===1?'':'S'}`,'outcome-stamp'),node('h3',result.level),node('p',result.findings.length?'Pause before you act. Do not reply, pay, share codes, or follow message links. Check through the company’s known app or website; for personal messages, use a contact you already know.':'We did not find a matching warning pattern. This is not verification. Check the sender and context independently before sharing anything or acting.'));const again=node('button','Check another message ↗','scan-again');again.addEventListener('click',()=>$('#compose-dialog').showModal());out.append(again);out.hidden=false;updateList();setPanel('desk');});
function celebrate(){if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;const party=node('div','','confetti');party.setAttribute('aria-hidden','true');for(let i=0;i<22;i++){const bit=node('i');bit.style.setProperty('--x',`${Math.random()*100}vw`);bit.style.setProperty('--r',`${Math.random()*720}deg`);bit.style.setProperty('--delay',`${Math.random()*.3}s`);bit.style.background=['#c94627','#d7ef74','#b6a1c8','#f3d78f'][i%4];party.append(bit);}document.body.append(party);setTimeout(()=>party.remove(),2000);}
openCase(0);
